
# Day 7 — Manual Translation Quality Inspection
#
# Purpose:
# Create a reproducible sample of translations generated
# by the fine-tuned MarianMT model.
#
# We will inspect:
# - 20 technical translations
# - 20 general-domain translations
#
# This complements BLEU and chrF automatic evaluation
# by identifying errors that metrics may not capture.

from pathlib import Path

import pandas as pd


# STEP 1 — Define input and output paths.

# Predictions generated by evaluate_finetuned.py.
PREDICTIONS_PATH = Path(
    "results/day7_predictions.csv"
)

# Output file for manual translation inspection.
OUTPUT_PATH = Path(
    "results/day7_manual_inspection.csv"
)

# Number of translations to inspect per domain.
SAMPLE_SIZE = 20

# Fixed seed ensures reproducible random sampling.
RANDOM_SEED = 42


def load_predictions():
    """
    Load and validate the fine-tuned model predictions.
    """

    # Verify that the predictions file exists.
    if not PREDICTIONS_PATH.exists():
        raise FileNotFoundError(
            f"Predictions file not found: {PREDICTIONS_PATH}"
        )

    # Load the CSV containing generated translations.
    df = pd.read_csv(PREDICTIONS_PATH)

    # Columns required for manual inspection.
    required_columns = [
        "language_pair",
        "domain",
        "sentence_id",
        "source",
        "reference",
        "prediction",
    ]

    # Identify any missing columns.
    missing_columns = [
        column
        for column in required_columns
        if column not in df.columns
    ]

    # Stop if the prediction file is incomplete.
    if missing_columns:
        raise ValueError(
            f"Missing columns: {missing_columns}"
        )

    # Return the validated predictions.
    return df


def sample_translations(df):
    """
    Randomly select translations from each domain.
    """

    samples = []

    # Evaluate both technical and general translations.
    for domain in ["technical", "general"]:

        # Select only translations from this domain.
        domain_df = df[
            df["domain"] == domain
        ].copy()

        # Verify that the domain contains translations.
        if domain_df.empty:
            raise ValueError(
                f"No predictions found for domain: {domain}"
            )

        # Select up to 20 translations.
        n_samples = min(
            SAMPLE_SIZE,
            len(domain_df),
        )

        # Random sampling with a fixed seed.
        sample = domain_df.sample(
            n=n_samples,
            random_state=RANDOM_SEED,
        ).copy()

        # Sort by sentence ID for easier inspection.
        sample = sample.sort_values(
            "sentence_id"
        )

        # Add columns for human evaluation.
        sample["error_category"] = ""
        sample["severity"] = ""
        sample["meaning_preserved"] = ""
        sample["comments"] = ""

        # Store the sampled domain.
        samples.append(sample)

        print(
            f"Selected {n_samples} translations "
            f"from {domain} dataset."
        )

    # Combine technical and general samples.
    result = pd.concat(
        samples,
        ignore_index=True,
    )

    return result


def save_inspection_file(df):
    """
    Save the selected translations for manual review.
    """

    # Create the output directory if necessary.
    OUTPUT_PATH.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    # Save translations and annotation columns.
    df.to_csv(
        OUTPUT_PATH,
        index=False,
        encoding="utf-8-sig",
    )

    print(
        f"Manual inspection file saved: {OUTPUT_PATH}"
    )


def main():
    """
    Execute the Day 7 manual inspection preparation.
    """

    # STEP 1 — Load fine-tuned model predictions.
    predictions = load_predictions()

    print(
        f"Loaded {len(predictions)} predictions."
    )

    # STEP 2 — Select reproducible samples.
    inspection_df = sample_translations(
        predictions
    )

    # STEP 3 — Save the inspection dataset.
    save_inspection_file(
        inspection_df
    )

    # STEP 4 — Display a preview in the terminal.
    print("\nManual inspection preview:")

    print(
        inspection_df[
            [
                "domain",
                "source",
                "reference",
                "prediction",
            ]
        ].head().to_string(index=False)
    )

    print("\nDay 7 manual inspection preparation completed.")


# Run main() only when this file is executed directly.
if __name__ == "__main__":
    main()
